# generated by tools/ail2py.py from config_validate.ail; edit the .ail until onelang s16
from config_core import *
from ail import flush_stdout
import sys

def main() -> int:
    if len(sys.argv) != 2:
        print('usage: config_validate INPUT', file=sys.stderr)
        return 2
    try:
        print(validate_config(sys.argv[1]))
        flush_stdout()
        return 0
    except UnicodeDecodeError as e:
        print(e.kind + ': ' + e.message, file=sys.stderr)
        return 4
    except ValueError as e:
        print(e.kind + ': ' + e.message, file=sys.stderr)
        return 2
    except OSError as e:
        print(e.kind + ': ' + e.message, file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
